def _tokenize_arabic(text):
    """
    Split Arabic text on whitespace and strip common attached prefixes
    (و ف ب ل ال) so that وَعَدْلِ → عدل can be matched.
    Returns a set of token variants (original + stripped forms).
    """
    tokens = set()
    prefixes = ["وال", "فال", "بال", "لل", "ال", "و", "ف", "ب", "ل", "ك"]
    for word in text.split():
        tokens.add(word)
        for prefix in prefixes:
            if word.startswith(prefix) and len(word) > len(prefix) + 1:
                tokens.add(word[len(prefix):])
                break  # strip only the longest matching prefix
    return tokens


def get_root_word_occurrences(df: pd.DataFrame) -> pd.DataFrame:
    """
    Detect root word occurrences using word-boundary-aware surface form matching.

    For each verse, tokenise the Arabic text into individual words (stripping
    common attached prefixes), then check whether any token exactly matches
    one of the curated surface forms for each root.

    This replaces the previous naive substring search (root in text) which
    caused false positives across unrelated Arabic words.
    """
    print("Detecting root word occurrences (word-boundary matching)...")

    # Pre-build a set of forms per root for O(1) lookup
    root_form_sets = {
        root: set(info["forms"])
        for root, info in COMMON_ROOTS.items()
    }

    records = []
    for _, row in tqdm(df.iterrows(), total=len(df), desc="Root scanning"):
        text        = row["arabic_text"]
        tokens      = _tokenize_arabic(text)

        for root, forms in root_form_sets.items():
            if tokens & forms:   # intersection: any token matches any form
                records.append({
                    "verse_id":         row["verse_id"],
                    "surah_number":     row["surah_number"],
                    "verse_number":     row["verse_number"],
                    "revelation":       row["revelation"],
                    "revelation_order": row["revelation_order"],
                    "root":             root,
                    "root_english":     COMMON_ROOTS[root]["english"],
                    "domain":           COMMON_ROOTS[root]["domain"],
                })

    result = pd.DataFrame(records)
    print(f"  Found {len(result)} root-verse associations.")
    return result


