def parse_tanzil_xml(xml_path: str) -> pd.DataFrame:
    if not os.path.exists(xml_path):
        raise FileNotFoundError(
            f"Tanzil XML not found at: {xml_path}\n"
            "Download from https://tanzil.net/download/\n"
            "Choose 'Simple (Clean)' format, save as data/quran-simple.xml"
        )
    print(f"Parsing Tanzil XML from {xml_path}...")
    tree = etree.parse(xml_path)
    root = tree.getroot()
    records = []
    for sura in tqdm(root.findall(".//sura"), desc="Parsing surahs"):
        surah_num = int(sura.get("index"))
        for aya in sura.findall("aya"):
            verse_num = int(aya.get("index"))
            text = aya.get("text", "")
            records.append({
                "surah_number": surah_num,
                "verse_number": verse_num,
                "arabic_text":  text
            })
    df = pd.DataFrame(records)
    print(f"  Loaded {len(df)} verses across {df['surah_number'].nunique()} surahs.")
    return df


def load_sahih_international(filepath: str = None) -> pd.DataFrame:
    if filepath and os.path.exists(filepath):
        print(f"Loading Sahih International from {filepath}...")
        df = pd.read_csv(filepath)
        df.columns = [c.lower().strip() for c in df.columns]
        col_map = {}
        for col in df.columns:
            if "surah" in col or "sura" in col or col == "chapter":
                col_map[col] = "surah_number"
            elif "verse" in col or "aya" in col or col == "ayah":
                col_map[col] = "verse_number"
            elif "text" in col or "translation" in col or "english" in col:
                col_map[col] = "english_text"
        df = df.rename(columns=col_map)
        return df[["surah_number", "verse_number", "english_text"]]

    print("Downloading Sahih International translation...")
    url = "https://cdn.jsdelivr.net/npm/quran-json@3.1.2/dist/quran_en.json"
    try:
        resp = requests.get(url, timeout=30)
        resp.raise_for_status()
        data = resp.json()
    except Exception as e:
        print(f"  Download failed: {e}")
        return pd.DataFrame(columns=["surah_number", "verse_number", "english_text"])

    records = []
    for surah_data in data:
        surah_idx = surah_data.get("id")
        for verse in surah_data.get("verses", []):
            records.append({
                "surah_number": surah_idx,
                "verse_number": verse.get("id"),
                "english_text": verse.get("translation", "")
            })
    df = pd.DataFrame(records)
    print(f"  Loaded {len(df)} translations.")
    return df


def merge_quran_data(arabic_df: pd.DataFrame, english_df: pd.DataFrame) -> pd.DataFrame:
    print("Merging Arabic and English datasets...")
    df = pd.merge(arabic_df, english_df,
                  on=["surah_number", "verse_number"], how="left")
    meta_records = []
    for surah_num, meta in SURAH_METADATA.items():
        meta_records.append({"surah_number": surah_num, **meta})
    meta_df = pd.DataFrame(meta_records)
    df = pd.merge(df, meta_df, on="surah_number", how="left")
    df["verse_id"] = (df["surah_number"].astype(str) + ":"
                      + df["verse_number"].astype(str))
    df = df.sort_values(["surah_number", "verse_number"]).reset_index(drop=True)
    print(f"  Final dataset: {len(df)} verses")
    return df


if __name__ == "__main__":
    import sys
    xml_path = sys.argv[1] if len(sys.argv) > 1 else "./data/quran-simple.xml"
    arabic   = parse_tanzil_xml(xml_path)
    english  = load_sahih_international()
    merged   = merge_quran_data(arabic, english)
    roots    = get_root_word_occurrences(merged)
    print("\nTop 20 roots by occurrence:")
    print(roots.groupby("root")["root_english"].first()
          .reset_index()
          .merge(roots.groupby("root")["verse_id"].count().reset_index(),
                 on="root")
          .sort_values("verse_id", ascending=False)
          .head(20)
          .to_string())